  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "月光淡得醉人 脚下黑了也不管"
        },
        {
          "id": "V1-02",
          "zh": "低着头走路 脚尖也看不清"
        },
        {
          "id": "V1-03",
          "zh": "踉跄两步往前 摔了都还没发觉"
        },
        {
          "id": "V1-04",
          "zh": "远处夜星 在眼里晕成一片"
        },
        {
          "id": "V1-05",
          "zh": "想做的事情 竟然一件都找不见"
        },
        {
          "id": "V1-06",
          "zh": "假装走得很急 头一直低垂"
        },
        {
          "id": "V1-07",
          "zh": "摔了一跤之后 还有笑声悬在背后"
        },
        {
          "id": "V1-08",
          "zh": "我垂着眼 装作什么都没听"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "淡月令人醉"
        },
        {
          "id": "V1-02",
          "zh": "暗处脚下看不见"
        },
        {
          "id": "V1-03",
          "zh": "摔倒也未察觉"
        },
        {
          "id": "V1-04",
          "zh": "远夜星光晕染开"
        },
        {
          "id": "V1-05",
          "zh": "找不到想做的事"
        },
        {
          "id": "V1-06",
          "zh": "装作匆忙低着头"
        },
        {
          "id": "V1-07",
          "zh": "摔倒后被人嘲笑"
        },
        {
          "id": "V1-08",
          "zh": "假装没注意到"
        }
      ]
    }
  ]
}

